# /// script
# requires-python = ">=3.11"
# dependencies = [
#     "jinja2",
#     "pdoc",
#     "ax253",
#     "kiss3",
#     "aprs3",
#     # Not on PyPI yet: document main until the first release.
#     "base-aprs-client @ git+https://github.com/python-aprs/base-aprs-client",
# ]
# ///
"""Build the python-aprs.org site into ``_site/``.

* ``index.html``: project overview and the libraries.
* ``changelog.html``: every library's GitHub releases, fetched at build time.
* ``docs/``: API reference for every library, generated by pdoc from the
  versions installed above (the latest release on PyPI).

Run it with ``uv run build.py``. Set ``GITHUB_TOKEN`` to avoid the
unauthenticated GitHub API rate limit.
"""

from __future__ import annotations

import datetime
import importlib.metadata
import json
import os
import shutil
import subprocess
import sys
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path

import jinja2

ROOT = Path(__file__).parent
OUT = ROOT / "_site"
ORG = "python-aprs"


@dataclass
class Library:
    repo: str  # GitHub repository name, also the PyPI distribution name
    module: str  # importable module documented by pdoc
    summary: str
    src: str  # path of the module in the repo, for "edit on GitHub" links
    on_pypi: bool = True
    releases: list[dict] = field(default_factory=list)

    @property
    def repo_url(self) -> str:
        return f"https://github.com/{ORG}/{self.repo}"

    @property
    def pypi_url(self) -> str:
        return f"https://pypi.org/project/{self.repo}/"

    @property
    def docs_url(self) -> str:
        return f"docs/{self.module}.html"

    @property
    def installed_version(self) -> str:
        return importlib.metadata.version(self.repo)

    @property
    def latest(self) -> dict | None:
        return next((r for r in self.releases if not r["prerelease"]), None)


# In dependency order: each library builds on the ones before it.
LIBRARIES = [
    Library(
        repo="ax253",
        module="ax253",
        summary="AX.25 frames and TNC2 text format: encode, decode and "
        "stream-decode raw frames.",
        src="src/ax253/",
    ),
    Library(
        repo="kiss3",
        module="kiss",
        summary="KISS framing for TNCs over serial and TCP, with blocking "
        "and asyncio interfaces.",
        src="kiss/",
    ),
    Library(
        repo="aprs3",
        module="aprs",
        summary="APRS packet encoding and decoding, plus APRS-IS and KISS connections.",
        src="aprs/",
    ),
    Library(
        repo="base-aprs-client",
        module="base_aprs_client",
        summary="APRS station behaviour for applications: messaging with "
        "acks and retries, status and position reports, and a packet log.",
        src="src/base_aprs_client/",
        on_pypi=False,
    ),
]


def fetch_releases(repo: str) -> list[dict]:
    """Return a repo's published releases, newest first.

    GitHub renders each release body to HTML for us (``body_html``), with
    @mentions and PR references linked, so no Markdown library is needed.
    """
    headers = {
        "Accept": "application/vnd.github.html+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "python-aprs.org-build",
    }
    if token := os.environ.get("GITHUB_TOKEN"):
        headers["Authorization"] = f"Bearer {token}"
    releases: list[dict] = []
    page = 1
    while True:
        url = f"https://api.github.com/repos/{ORG}/{repo}/releases?per_page=100&page={page}"
        with urllib.request.urlopen(
            urllib.request.Request(url, headers=headers)
        ) as resp:
            batch = json.load(resp)
        releases.extend(r for r in batch if not r["draft"])
        if len(batch) < 100:
            break
        page += 1
    for r in releases:
        r["date"] = datetime.datetime.fromisoformat(r["published_at"]).date()
    releases.sort(key=lambda r: r["published_at"], reverse=True)
    return releases


def build_api_docs() -> None:
    """Render every library's API reference into one pdoc site.

    One pdoc run covers all the modules, so cross-library references (an
    aprs class that takes a kiss transport, say) link to each other and the
    search box covers everything.
    """
    cmd = [
        sys.executable, "-m", "pdoc",
        "--docformat", "restructuredtext",
        "--template-directory", str(ROOT / "templates" / "pdoc"),
        "--output-directory", str(OUT / "docs"),
        "--logo", "/logo.svg",
        "--logo-link", "/",
        "--favicon", "/logo.svg",
        "--footer-text", "python-aprs.org",
    ]  # fmt: skip
    for lib in LIBRARIES:
        cmd += ["--edit-url", f"{lib.module}={lib.repo_url}/blob/main/{lib.src}"]
    cmd += [lib.module for lib in LIBRARIES]
    subprocess.run(cmd, check=True)


def main() -> None:
    shutil.rmtree(OUT, ignore_errors=True)
    shutil.copytree(ROOT / "static", OUT)

    for lib in LIBRARIES:
        lib.releases = fetch_releases(lib.repo)

    env = jinja2.Environment(
        loader=jinja2.FileSystemLoader(ROOT / "templates"),
        autoescape=True,
        trim_blocks=True,
        lstrip_blocks=True,
    )
    context = {
        "libraries": LIBRARIES,
        "recent": sorted(
            ((lib, r) for lib in LIBRARIES for r in lib.releases),
            key=lambda pair: pair[1]["published_at"],
            reverse=True,
        )[:6],
        "built": datetime.datetime.now(datetime.UTC),
    }
    for page in ("index.html", "changelog.html", "404.html"):
        (OUT / page).write_text(env.get_template(page).render(page=page, **context))

    build_api_docs()
    print(f"Built {OUT}")


if __name__ == "__main__":
    main()
